#include <vector>
#include <stack>
#include <algorithm>

int largestRectangleArea(std::vector<int>& heights) {
    heights.push_back(0); // Sentinel
    std::stack<int> s;
    int maxArea = 0;
    for (int i = 0; i < (int)heights.size(); ++i) {
        while (!s.empty() && heights[s.top()] > heights[i]) {
            int h = heights[s.top()];
            s.pop();
            int w = s.empty() ? i : i - s.top() - 1;
            maxArea = std::max(maxArea, h * w);
        }
        s.push(i);
    }
    return maxArea;
}

